0081 	var previousID, previousHash string
0082 	err = tx.QueryRow("SELECT artifact_id,content_hash FROM retrieval_snapshots WHERE project=? AND root_id=? AND relative_path=? AND status='CURRENT'", project, rootID, relative).Scan(&previousID, &previousHash)
0083 	if err != nil && !errors.Is(err, sql.ErrNoRows) {
0084 		return nil, err
0085 	}
0086 	if previousID != "" && previousHash == Digest(data) {
0087 		return load(tx, project, "Artifact", previousID)
0088 	}
0089 	profile, err := singleton(tx, project, "ProjectProfile")
0090 	if err != nil {
0091 		return nil, err
0092 	}
0093 	if previousID != "" {
