0108 	}
0109 	_, err = tx.Exec("INSERT INTO retrieval_snapshots(project,artifact_id,root_id,relative_path,content_hash,root_revision,status) VALUES(?,?,?,?,?,?,'CURRENT')", project, a["id"], rootID, relative, a["content_hash"], rootRev)
0110 	if err != nil {
0111 		return nil, err
0112 	}
0113 	var indexed int
0114 	if err = tx.QueryRow("SELECT count(*) FROM retrieval_index WHERE project=? AND artifact_id=?", project, a["id"]).Scan(&indexed); err != nil {
0115 		return nil, err
0116 	}
0117 	if indexed == 0 {
0118 		if _, err = tx.Exec("INSERT INTO retrieval_fts(project,artifact_id,body) VALUES(?,?,?)", project, a["id"], string(data)); err != nil {
0119 			return nil, err
0120 		}
0121 		var rowid int64
0122 		if err = tx.QueryRow("SELECT last_insert_rowid()").Scan(&rowid); err != nil {
0123 			return nil, err
0124 		}
0125 		if _, err = tx.Exec("INSERT INTO retrieval_index(project,artifact_id,fts_rowid,index_revision,content_hash) VALUES(?,?,?,1,?)", project, a["id"], rowid, a["content_hash"]); err != nil {
0126 			return nil, err
0127 		}
0128 	}
0129 	if !containsSnapshot(Arr(profile, "read_snapshot_ids"), Str(a, "id")) {
0130 		profile["read_snapshot_ids"] = append(Arr(profile, "read_snapshot_ids"), a["id"])
0131 	}
0132 	if err = s.saveSnapshotProfile(tx, p, profile); err != nil {
